extension DailyVerse {
    public static let all: [DailyVerse] = [
        DailyVerse(reference: BibleReference(book: 19, chapter: 23, verseStart: 1, verseEnd: 1),
                   chinese: "耶和华是我的牧者，我必不至缺乏。",
                   english: "The LORD is my shepherd; I shall not want."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 3, verseStart: 16, verseEnd: 16),
                   chinese: "神爱世人，甚至将他的独生子赐给他们，叫一切信他的，不至灭亡，反得永生。",
                   english: "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."),
        DailyVerse(reference: BibleReference(book: 20, chapter: 3, verseStart: 5, verseEnd: 6),
                   chinese: "你要专心仰赖耶和华，不可倚靠自己的聪明，在你一切所行的事上都要认定他，他必指引你的路。",
                   english: "Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths."),
        DailyVerse(reference: BibleReference(book: 50, chapter: 4, verseStart: 13, verseEnd: 13),
                   chinese: "我靠着那加给我力量的，凡事都能作。",
                   english: "I can do all things through Christ which strengtheneth me."),
        DailyVerse(reference: BibleReference(book: 23, chapter: 40, verseStart: 31, verseEnd: 31),
                   chinese: "但那等候耶和华的必从新得力。他们必如鹰展翅上腾；他们奔跑却不困倦，行走却不疲乏。",
                   english: "But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint."),
        DailyVerse(reference: BibleReference(book: 45, chapter: 8, verseStart: 28, verseEnd: 28),
                   chinese: "我们晓得万事都互相效力，叫爱神的人得益处，就是按他旨意被召的人。",
                   english: "And we know that all things work together for good to them that love God, to them who are the called according to his purpose."),
        DailyVerse(reference: BibleReference(book: 24, chapter: 29, verseStart: 11, verseEnd: 11),
                   chinese: "耶和华说：我知道我向你们所怀的意念是赐平安的意念，不是降灾祸的意念，要叫你们末后有指望。",
                   english: "For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end."),
        DailyVerse(reference: BibleReference(book: 40, chapter: 11, verseStart: 28, verseEnd: 28),
                   chinese: "凡劳苦担重担的人可以到我这里来，我就使你们得安息。",
                   english: "Come unto me, all ye that labour and are heavy laden, and I will give you rest."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 119, verseStart: 105, verseEnd: 105),
                   chinese: "你的话是我脚前的灯，是我路上的光。",
                   english: "Thy word is a lamp unto my feet, and a light unto my path."),
        DailyVerse(reference: BibleReference(book: 50, chapter: 4, verseStart: 6, verseEnd: 7),
                   chinese: "应当一无挂虑，只要凡事借着祷告、祈求，和感谢，将你们所要的告诉神。神所赐出人意外的平安，必在基督耶稣里保守你们的心怀意念。",
                   english: "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God. And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus."),
        DailyVerse(reference: BibleReference(book: 6, chapter: 1, verseStart: 9, verseEnd: 9),
                   chinese: "我岂没有吩咐你么？你当刚强壮胆！不要惧怕，也不要惊惶；因为你无论往那里去，耶和华你的神必与你同在。」",
                   english: "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest."),
        DailyVerse(reference: BibleReference(book: 47, chapter: 5, verseStart: 17, verseEnd: 17),
                   chinese: "若有人在基督里，他就是新造的人，旧事已过，都变成新的了。",
                   english: "Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 46, verseStart: 1, verseEnd: 1),
                   chinese: "神是我们的避难所，是我们的力量，是我们在患难中随时的帮助。",
                   english: "God is our refuge and strength, a very present help in trouble."),
        DailyVerse(reference: BibleReference(book: 48, chapter: 2, verseStart: 20, verseEnd: 20),
                   chinese: "我已经与基督同钉十字架，现在活着的不再是我，乃是基督在我里面活着；并且我如今在肉身活着，是因信神的儿子而活；他是爱我，为我舍己。",
                   english: "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me."),
        DailyVerse(reference: BibleReference(book: 23, chapter: 41, verseStart: 10, verseEnd: 10),
                   chinese: "你不要害怕，因为我与你同在；不要惊惶，因为我是你的神。我必坚固你，我必帮助你；我必用我公义的右手扶持你。",
                   english: "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness."),
        DailyVerse(reference: BibleReference(book: 49, chapter: 2, verseStart: 8, verseEnd: 9),
                   chinese: "你们得救是本乎恩，也因着信；这并不是出于自己，乃是神所赐的；也不是出于行为，免得有人自夸。",
                   english: "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Not of works, lest any man should boast."),
        DailyVerse(reference: BibleReference(book: 25, chapter: 3, verseStart: 22, verseEnd: 23),
                   chinese: "我们不至消灭，是出于耶和华诸般的慈爱；是因他的怜悯不至断绝。每早晨，这都是新的；你的诚实极其广大！",
                   english: "It is of the LORD’S mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness."),
        DailyVerse(reference: BibleReference(book: 58, chapter: 11, verseStart: 1, verseEnd: 1),
                   chinese: "信就是所望之事的实底，是未见之事的确据。",
                   english: "Now faith is the substance of things hoped for, the evidence of things not seen."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 46, verseStart: 10, verseEnd: 10),
                   chinese: "你们要休息，要知道我是神！我必在外邦中被尊崇，在遍地上也被尊崇。",
                   english: "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth."),
        DailyVerse(reference: BibleReference(book: 40, chapter: 6, verseStart: 33, verseEnd: 33),
                   chinese: "你们要先求他的国和他的义，这些东西都要加给你们了。",
                   english: "But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you."),
        DailyVerse(reference: BibleReference(book: 20, chapter: 4, verseStart: 23, verseEnd: 23),
                   chinese: "你要保守你心，胜过保守一切〔或作：你要切切保守你心〕，因为一生的果效是由心发出。",
                   english: "Keep thy heart with all diligence; for out of it are the issues of life."),
        DailyVerse(reference: BibleReference(book: 59, chapter: 1, verseStart: 5, verseEnd: 5),
                   chinese: "你们中间若有缺少智慧的，应当求那厚赐与众人、也不斥责人的神，主就必赐给他。",
                   english: "If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 27, verseStart: 1, verseEnd: 1),
                   chinese: "耶和华是我的亮光，是我的拯救，我还怕谁呢？耶和华是我性命的保障〔或作：力量〕，我还惧谁呢？",
                   english: "The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?"),
        DailyVerse(reference: BibleReference(book: 60, chapter: 5, verseStart: 7, verseEnd: 7),
                   chinese: "你们要将一切的忧虑卸给神，因为他顾念你们。",
                   english: "Casting all your care upon him; for he careth for you."),
        DailyVerse(reference: BibleReference(book: 5, chapter: 31, verseStart: 6, verseEnd: 6),
                   chinese: "你们当刚强壮胆，不要害怕，也不要畏惧他们，因为耶和华你的神和你同去。他必不撇下你，也不丢弃你。」",
                   english: "Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee."),
        DailyVerse(reference: BibleReference(book: 62, chapter: 1, verseStart: 9, verseEnd: 9),
                   chinese: "我们若认自己的罪，神是信实的，是公义的，必要赦免我们的罪，洗净我们一切的不义。",
                   english: "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 37, verseStart: 5, verseEnd: 5),
                   chinese: "当将你的事交托耶和华，并倚靠他，他就必成全。",
                   english: "Commit thy way unto the LORD; trust also in him; and he shall bring it to pass."),
        DailyVerse(reference: BibleReference(book: 40, chapter: 6, verseStart: 34, verseEnd: 34),
                   chinese: "所以，不要为明天忧虑，因为明天自有明天的忧虑；一天的难处一天当就彀了。」",
                   english: "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof."),
        DailyVerse(reference: BibleReference(book: 23, chapter: 26, verseStart: 3, verseEnd: 3),
                   chinese: "坚心倚赖你的，你必保守他十分平安，因为他倚靠你。",
                   english: "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 14, verseStart: 6, verseEnd: 6),
                   chinese: "耶稣说：「我就是道路、真理、生命；若不借着我，没有人能到父那里去。",
                   english: "Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 34, verseStart: 8, verseEnd: 8),
                   chinese: "你们要尝尝主恩的滋味，便知道他是美善；投靠他的人有福了！",
                   english: "O taste and see that the LORD is good: blessed is the man that trusteth in him."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 14, verseStart: 27, verseEnd: 27),
                   chinese: "我留下平安给你们；我将我的平安赐给你们。我所赐的，不像世人所赐的。你们心里不要忧愁，也不要胆怯。",
                   english: "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid."),
        DailyVerse(reference: BibleReference(book: 33, chapter: 6, verseStart: 8, verseEnd: 8),
                   chinese: "世人哪，耶和华已指示你何为善。他向你所要的是甚么呢？只要你行公义，好怜悯，存谦卑的心，与你的神同行。",
                   english: "He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?"),
        DailyVerse(reference: BibleReference(book: 43, chapter: 15, verseStart: 5, verseEnd: 5),
                   chinese: "我是葡萄树，你们是枝子。常在我里面的，我也常在他里面，这人就多结果子；因为离了我，你们就不能作甚么。",
                   english: "I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 51, verseStart: 10, verseEnd: 10),
                   chinese: "神啊，求你为我造清洁的心，使我里面重新有正直〔或作：坚定〕的灵。",
                   english: "Create in me a clean heart, O God; and renew a right spirit within me."),
        DailyVerse(reference: BibleReference(book: 45, chapter: 12, verseStart: 2, verseEnd: 2),
                   chinese: "不要效法这个世界，只要心意更新而变化，叫你们察验何为神的善良、纯全、可喜悦的旨意。",
                   english: "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God."),
        DailyVerse(reference: BibleReference(book: 36, chapter: 3, verseStart: 17, verseEnd: 17),
                   chinese: "耶和华你的神是施行拯救、大有能力的主。他在你中间必因你欢欣喜乐，默然爱你，且因你喜乐而欢呼。",
                   english: "The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing."),
        DailyVerse(reference: BibleReference(book: 45, chapter: 5, verseStart: 8, verseEnd: 8),
                   chinese: "惟有基督在我们还作罪人的时候为我们死，神的爱就在此向我们显明了。",
                   english: "But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 90, verseStart: 12, verseEnd: 12),
                   chinese: "求你指教我们怎样数算自己的日子，好叫我们得着智慧的心。",
                   english: "So teach us to number our days, that we may apply our hearts unto wisdom."),
        DailyVerse(reference: BibleReference(book: 45, chapter: 8, verseStart: 38, verseEnd: 39),
                   chinese: "因为我深信无论是死，是生，是天使，是掌权的，是有能的，是现在的事，是将来的事，是高处的，是低处的，是别的受造之物，都不能叫我们与神的爱隔绝；这爱是在我们的主基督耶稣里的。",
                   english: "For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come, Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord."),
        DailyVerse(reference: BibleReference(book: 4, chapter: 6, verseStart: 24, verseEnd: 26),
                   chinese: "『愿耶和华赐福给你，保护你。愿耶和华使他的脸光照你，赐恩给你。愿耶和华向你仰脸，赐你平安。』",
                   english: "The LORD bless thee, and keep thee: The LORD make his face shine upon thee, and be gracious unto thee: The LORD lift up his countenance upon thee, and give thee peace."),
        DailyVerse(reference: BibleReference(book: 46, chapter: 13, verseStart: 4, verseEnd: 7),
                   chinese: "爱是恒久忍耐，又有恩慈；爱是不嫉妒；爱是不自夸，不张狂，不作害羞的事，不求自己的益处，不轻易发怒，不计算人的恶，不喜欢不义，只喜欢真理；凡事包容，凡事相信，凡事盼望，凡事忍耐。",
                   english: "Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up, Doth not behave itself unseemly, seeketh not her own, is not easily provoked, thinketh no evil; Rejoiceth not in iniquity, but rejoiceth in the truth; Beareth all things, believeth all things, hopeth all things, endureth all things."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 91, verseStart: 1, verseEnd: 1),
                   chinese: "住在至高者隐密处的，必住在全能者的荫下。",
                   english: "He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty."),
        DailyVerse(reference: BibleReference(book: 46, chapter: 10, verseStart: 13, verseEnd: 13),
                   chinese: "你们所遇见的试探，无非是人所能受的。神是信实的，必不叫你们受试探过于所能受的；在受试探的时候，总要给你们开一条出路，叫你们能忍受得住。",
                   english: "There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it."),
        DailyVerse(reference: BibleReference(book: 20, chapter: 16, verseStart: 3, verseEnd: 3),
                   chinese: "你所作的，要交托耶和华，你所谋的，就必成立。",
                   english: "Commit thy works unto the LORD, and thy thoughts shall be established."),
        DailyVerse(reference: BibleReference(book: 47, chapter: 12, verseStart: 9, verseEnd: 9),
                   chinese: "他对我说：「我的恩典彀你用的，因为我的能力是在人的软弱上显得完全。」所以，我更喜欢夸自己的软弱，好叫基督的能力覆庇我。",
                   english: "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 103, verseStart: 2, verseEnd: 2),
                   chinese: "我的心哪，你要称颂耶和华！不可忘记他的一切恩惠！",
                   english: "Bless the LORD, O my soul, and forget not all his benefits:"),
        DailyVerse(reference: BibleReference(book: 48, chapter: 5, verseStart: 22, verseEnd: 23),
                   chinese: "圣灵所结的果子，就是仁爱、喜乐、和平、忍耐、恩慈、良善、信实、温柔、节制。这样的事，没有律法禁止。",
                   english: "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law."),
        DailyVerse(reference: BibleReference(book: 23, chapter: 43, verseStart: 1, verseEnd: 1),
                   chinese: "雅各啊，创造你的耶和华，以色列啊，造成你的那位，现在如此说：你不要害怕！因为我救赎了你。我曾提你的名召你，你是属我的。",
                   english: "But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine."),
        DailyVerse(reference: BibleReference(book: 49, chapter: 3, verseStart: 20, verseEnd: 20),
                   chinese: "神能照着运行在我们心里的大力，充充足足的成就一切，超过我们所求所想的。",
                   english: "Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,"),
        DailyVerse(reference: BibleReference(book: 19, chapter: 118, verseStart: 24, verseEnd: 24),
                   chinese: "这是耶和华所定的日子，我们在其中要高兴欢喜！",
                   english: "This is the day which the LORD hath made; we will rejoice and be glad in it."),
        DailyVerse(reference: BibleReference(book: 50, chapter: 1, verseStart: 6, verseEnd: 6),
                   chinese: "我深信那在你们心里动了善工的，必成全这工，直到耶稣基督的日子。",
                   english: "Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:"),
        DailyVerse(reference: BibleReference(book: 20, chapter: 16, verseStart: 9, verseEnd: 9),
                   chinese: "人心筹算自己的道路；惟耶和华指引他的脚步。",
                   english: "A man’s heart deviseth his way: but the LORD directeth his steps."),
        DailyVerse(reference: BibleReference(book: 50, chapter: 4, verseStart: 4, verseEnd: 4),
                   chinese: "你们要靠主常常喜乐。我再说，你们要喜乐。",
                   english: "Rejoice in the Lord alway: and again I say, Rejoice."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 121, verseStart: 1, verseEnd: 2),
                   chinese: "我要向山举目；我的帮助从何而来？我的帮助从造天地的耶和华而来。",
                   english: "I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the LORD, which made heaven and earth."),
        DailyVerse(reference: BibleReference(book: 51, chapter: 3, verseStart: 23, verseEnd: 23),
                   chinese: "无论作甚么，都要从心里作，像是给主作的，不是给人作的，",
                   english: "And whatsoever ye do, do it heartily, as to the Lord, and not unto men;"),
        DailyVerse(reference: BibleReference(book: 21, chapter: 3, verseStart: 1, verseEnd: 1),
                   chinese: "凡事都有定期，天下万务都有定时。",
                   english: "To every thing there is a season, and a time to every purpose under the heaven:"),
        DailyVerse(reference: BibleReference(book: 52, chapter: 5, verseStart: 16, verseEnd: 18),
                   chinese: "要常常喜乐，不住的祷告，凡事谢恩；因为这是神在基督耶稣里向你们所定的旨意。",
                   english: "Rejoice evermore. Pray without ceasing. In every thing give thanks: for this is the will of God in Christ Jesus concerning you."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 139, verseStart: 23, verseEnd: 24),
                   chinese: "神啊，求你鉴察我，知道我的心思，试炼我，知道我的意念，看在我里面有甚么恶行没有，引导我走永生的道路。",
                   english: "Search me, O God, and know my heart: try me, and know my thoughts: And see if there be any wicked way in me, and lead me in the way everlasting."),
        DailyVerse(reference: BibleReference(book: 55, chapter: 1, verseStart: 7, verseEnd: 7),
                   chinese: "因为神赐给我们，不是胆怯的心，乃是刚强、仁爱、谨守的心。",
                   english: "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind."),
        DailyVerse(reference: BibleReference(book: 23, chapter: 53, verseStart: 5, verseEnd: 5),
                   chinese: "哪知他为我们的过犯受害，为我们的罪孽压伤。因他受的刑罚，我们得平安；因他受的鞭伤，我们得医治。",
                   english: "But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed."),
        DailyVerse(reference: BibleReference(book: 55, chapter: 3, verseStart: 16, verseEnd: 17),
                   chinese: "圣经都是神所默示的〔或作：凡神所默示的圣经〕，于教训、督责、使人归正、教导人学义都是有益的，叫属神的人得以完全，预备行各样的善事。",
                   english: "All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness: That the man of God may be perfect, throughly furnished unto all good works."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 16, verseStart: 11, verseEnd: 11),
                   chinese: "你必将生命的道路指示我。在你面前有满足的喜乐；在你右手中有永远的福乐。",
                   english: "Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore."),
        DailyVerse(reference: BibleReference(book: 58, chapter: 4, verseStart: 16, verseEnd: 16),
                   chinese: "所以，我们只管坦然无惧的来到施恩的宝座前，为要得怜恤，蒙恩惠，作随时的帮助。",
                   english: "Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 19, verseStart: 14, verseEnd: 14),
                   chinese: "耶和华我的磐石，我的救赎主啊，愿我口中的言语、心里的意念在你面前蒙悦纳。",
                   english: "Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer."),
        DailyVerse(reference: BibleReference(book: 58, chapter: 12, verseStart: 2, verseEnd: 2),
                   chinese: "仰望为我们信心创始成终的耶稣〔或作：仰望那将真道创始成终的耶稣〕。他因那摆在前面的喜乐，就轻看羞辱，忍受了十字架的苦难，便坐在神宝座的右边。",
                   english: "Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God."),
        DailyVerse(reference: BibleReference(book: 23, chapter: 55, verseStart: 8, verseEnd: 9),
                   chinese: "耶和华说：我的意念非同你们的意念；我的道路非同你们的道路。天怎样高过地，照样，我的道路高过你们的道路；我的意念高过你们的意念。",
                   english: "For my thoughts are not your thoughts, neither are your ways my ways, saith the LORD. For as the heavens are higher than the earth, so are my ways higher than your ways, and my thoughts than your thoughts."),
        DailyVerse(reference: BibleReference(book: 58, chapter: 13, verseStart: 8, verseEnd: 8),
                   chinese: "耶稣基督，昨日、今日、一直到永远、是一样的。",
                   english: "Jesus Christ the same yesterday, and to day, and for ever."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 42, verseStart: 1, verseEnd: 1),
                   chinese: "神啊，我的心切慕你，如鹿切慕溪水。",
                   english: "As the hart panteth after the water brooks, so panteth my soul after thee, O God."),
        DailyVerse(reference: BibleReference(book: 59, chapter: 1, verseStart: 2, verseEnd: 3),
                   chinese: "我的弟兄们，你们落在百般试炼中，都要以为大喜乐；因为知道你们的信心经过试验，就生忍耐。",
                   english: "My brethren, count it all joy when ye fall into divers temptations; Knowing this, that the trying of your faith worketh patience."),
        DailyVerse(reference: BibleReference(book: 35, chapter: 3, verseStart: 17, verseEnd: 18),
                   chinese: "虽然无花果树不发旺，葡萄树不结果，橄榄树也不效力，田地不出粮食，圈中绝了羊，棚内也没有牛；然而，我要因耶和华欢欣，因救我的神喜乐。",
                   english: "Although the fig tree shall not blossom, neither shall fruit be in the vines; the labour of the olive shall fail, and the fields shall yield no meat; the flock shall be cut off from the fold, and there shall be no herd in the stalls: Yet I will rejoice in the LORD, I will joy in the God of my salvation."),
        DailyVerse(reference: BibleReference(book: 62, chapter: 4, verseStart: 19, verseEnd: 19),
                   chinese: "我们爱，因为神先爱我们。",
                   english: "We love him, because he first loved us."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 73, verseStart: 26, verseEnd: 26),
                   chinese: "我的肉体和我的心肠衰残；但神是我心里的力量，又是我的福分，直到永远。",
                   english: "My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever."),
        DailyVerse(reference: BibleReference(book: 62, chapter: 4, verseStart: 18, verseEnd: 18),
                   chinese: "爱里没有惧怕；爱既完全，就把惧怕除去。因为惧怕里含着刑罚，惧怕的人在爱里未得完全。",
                   english: "There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 23, verseStart: 4, verseEnd: 4),
                   chinese: "我虽然行过死荫的幽谷，也不怕遭害，因为你与我同在；你的杖，你的竿，都安慰我。",
                   english: "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."),
        DailyVerse(reference: BibleReference(book: 66, chapter: 3, verseStart: 20, verseEnd: 20),
                   chinese: "看哪，我站在门外叩门，若有听见我声音就开门的，我要进到他那里去，我与他，他与我一同坐席。",
                   english: "Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 145, verseStart: 18, verseEnd: 18),
                   chinese: "凡求告耶和华的，就是诚心求告他的，耶和华便与他们相近。",
                   english: "The LORD is nigh unto all them that call upon him, to all that call upon him in truth."),
        DailyVerse(reference: BibleReference(book: 40, chapter: 5, verseStart: 16, verseEnd: 16),
                   chinese: "你们的光也当这样照在人前，叫他们看见你们的好行为，便将荣耀归给你们在天上的父。」",
                   english: "Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven."),
        DailyVerse(reference: BibleReference(book: 1, chapter: 1, verseStart: 1, verseEnd: 1),
                   chinese: "起初神创造天地。",
                   english: "In the beginning God created the heaven and the earth."),
        DailyVerse(reference: BibleReference(book: 40, chapter: 22, verseStart: 37, verseEnd: 39),
                   chinese: "耶稣对他说：「你要尽心、尽性、尽意爱主你的神。这是诫命中的第一，且是最大的。其次也相倣，就是要爱人如己。",
                   english: "Jesus said unto him, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind. This is the first and great commandment. And the second is like unto it, Thou shalt love thy neighbour as thyself."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 62, verseStart: 1, verseEnd: 1),
                   chinese: "我的心默默无声，专等候神；我的救恩是从他而来。",
                   english: "Truly my soul waiteth upon God: from him cometh my salvation."),
        DailyVerse(reference: BibleReference(book: 40, chapter: 28, verseStart: 20, verseEnd: 20),
                   chinese: "凡我所吩咐你们的，都教训他们遵守，我就常与你们同在，直到世界的末了。",
                   english: "Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen."),
        DailyVerse(reference: BibleReference(book: 19, chapter: 100, verseStart: 4, verseEnd: 5),
                   chinese: "当称谢进入他的门；当赞美进入他的院。当感谢他，称颂他的名！因为耶和华本为善。他的慈爱存到永远；他的信实直到万代。",
                   english: "Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name. For the LORD is good; his mercy is everlasting; and his truth endureth to all generations."),
        DailyVerse(reference: BibleReference(book: 40, chapter: 7, verseStart: 7, verseEnd: 7),
                   chinese: "「你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。",
                   english: "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:"),
        DailyVerse(reference: BibleReference(book: 40, chapter: 5, verseStart: 8, verseEnd: 8),
                   chinese: "清心的人有福了！因为他们必得见神。",
                   english: "Blessed are the pure in heart: for they shall see God."),
        DailyVerse(reference: BibleReference(book: 42, chapter: 1, verseStart: 37, verseEnd: 37),
                   chinese: "因为出于神的话，没有一句不带能力的。」",
                   english: "For with God nothing shall be impossible."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 1, verseStart: 14, verseEnd: 14),
                   chinese: "道成了肉身，住在我们中间，充充满满的有恩典有真理。我们也见过他的荣光，正是父独生子的荣光。",
                   english: "And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 8, verseStart: 12, verseEnd: 12),
                   chinese: "耶稣又对众人说：「我是世界的光。跟从我的，就不在黑暗里走，必要得着生命的光。」",
                   english: "Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 10, verseStart: 10, verseEnd: 10),
                   chinese: "盗贼来，无非要偷窃，杀害，毁坏；我来了，是要叫羊〔或作：人〕得生命，并且得的更丰盛。",
                   english: "The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 11, verseStart: 25, verseEnd: 26),
                   chinese: "耶稣对她说：「复活在我，生命也在我。信我的人虽然死了，也必复活，凡活着信我的人必永远不死。你信这话么？」",
                   english: "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live: And whosoever liveth and believeth in me shall never die. Believest thou this?"),
        DailyVerse(reference: BibleReference(book: 43, chapter: 13, verseStart: 34, verseEnd: 34),
                   chinese: "我赐给你们一条新命令，乃是叫你们彼此相爱；我怎样爱你们，你们也要怎样相爱。",
                   english: "A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another."),
        DailyVerse(reference: BibleReference(book: 43, chapter: 16, verseStart: 33, verseEnd: 33),
                   chinese: "我将这些事告诉你们，是要叫你们在我里面有平安。在世上你们有苦难，但你们可以放心，我已经胜了世界。」",
                   english: "These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world."),
        DailyVerse(reference: BibleReference(book: 44, chapter: 1, verseStart: 8, verseEnd: 8),
                   chinese: "但圣灵降临在你们身上，你们就必得着能力，并要在耶路撒冷、犹太全地，和撒玛利亚，直到地极，作我的见证。」",
                   english: "But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth."),
        DailyVerse(reference: BibleReference(book: 45, chapter: 10, verseStart: 17, verseEnd: 17),
                   chinese: "可见信道是从听道来的，听道是从基督的话来的。",
                   english: "So then faith cometh by hearing, and hearing by the word of God."),
        DailyVerse(reference: BibleReference(book: 45, chapter: 12, verseStart: 12, verseEnd: 12),
                   chinese: "在指望中要喜乐，在患难中要忍耐，祷告要恒切。",
                   english: "Rejoicing in hope; patient in tribulation; continuing instant in prayer;"),
        DailyVerse(reference: BibleReference(book: 45, chapter: 15, verseStart: 13, verseEnd: 13),
                   chinese: "但愿使人有盼望的神，因信将诸般的喜乐、平安充满你们的心，使你们借着圣灵的能力大有盼望。",
                   english: "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost."),
        DailyVerse(reference: BibleReference(book: 49, chapter: 4, verseStart: 32, verseEnd: 32),
                   chinese: "并要以恩慈相待，存怜悯的心，彼此饶恕，正如神在基督里饶恕了你们一样。",
                   english: "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you."),
        DailyVerse(reference: BibleReference(book: 49, chapter: 6, verseStart: 10, verseEnd: 10),
                   chinese: "我还有末了的话：你们要靠着主，倚赖他的大能大力，作刚强的人。",
                   english: "Finally, my brethren, be strong in the Lord, and in the power of his might."),
    ]
}
